//! Sound: real gunshot and knife recordings, our own synthesized effects, a
//! distant-gunfight bed, and adaptive suspense music remixed from the voodoo
//! drum track. Files live in `assets/audio/local` (third-party material, kept
//! out of git: check the licences before release) and `assets/audio/synth`
//! (generated by us). A missing file just means silence for that sound.
//!
//! Music: two loops of the same length play together. The calm one is slowed,
//! pitched down and drowned in reverb with a drone and a slow heartbeat; the
//! tense one is the same drums, hard and distorted, over a dissonant pad and a
//! faster heartbeat. The game crossfades between them as the danger rises.

use crate::ai::{AiState, Guard};
use crate::weapons::{Fx, Health};
use crate::*;
use bevy::audio::{AudioPlayer, AudioSink, AudioSinkPlayback, AudioSource, PlaybackMode, PlaybackSettings, Volume};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sfx {
    Ak,
    Pistol,
    M50,
    KnifeHit,
    KnifeSwish,
    Sniper,
    Explosion,
    Reload,
    Plip,
    Hit,
}

#[derive(Clone)]
pub struct AudioAssets {
    ak: Vec<Handle<AudioSource>>,
    pistol: Vec<Handle<AudioSource>>,
    m50: Vec<Handle<AudioSource>>,
    knife_hit: Handle<AudioSource>,
    knife_swish: Handle<AudioSource>,
    sniper: Handle<AudioSource>,
    explosion: Handle<AudioSource>,
    reload: Handle<AudioSource>,
    plip: Handle<AudioSource>,
    hit: Handle<AudioSource>,
    pub heli: Handle<AudioSource>,
    pub ambience: Handle<AudioSource>,
    pub calm: Handle<AudioSource>,
    pub tense: Handle<AudioSource>,
    pub intro: Handle<AudioSource>,
}

impl AudioAssets {
    pub fn load(server: &AssetServer) -> Self {
        let many = |name: &str, n: usize| -> Vec<Handle<AudioSource>> {
            (1..=n).map(|i| server.load(format!("audio/local/{name}_{i}.wav"))).collect()
        };
        Self {
            ak: many("ak", 5),
            pistol: many("pistol", 4),
            m50: many("m50", 4),
            knife_hit: server.load("audio/local/knife_hit.wav"),
            knife_swish: server.load("audio/local/knife_swish.wav"),
            sniper: server.load("audio/local/sniper_shot.wav"),
            explosion: server.load("audio/synth/explosion.wav"),
            reload: server.load("audio/synth/reload.wav"),
            plip: server.load("audio/synth/plip.wav"),
            hit: server.load("audio/synth/hit.wav"),
            heli: server.load("audio/synth/heli_loop.wav"),
            ambience: server.load("audio/local/fight_ambience.wav"),
            calm: server.load("audio/local/music_calm.wav"),
            tense: server.load("audio/local/music_tense.wav"),
            intro: server.load("audio/local/intro_mystery.wav"),
        }
    }

    fn pick(&self, s: Sfx, r: f32) -> Handle<AudioSource> {
        let from = |v: &Vec<Handle<AudioSource>>| v[((r * v.len() as f32) as usize).min(v.len() - 1)].clone();
        match s {
            Sfx::Ak => from(&self.ak),
            Sfx::Pistol => from(&self.pistol),
            Sfx::M50 => from(&self.m50),
            Sfx::KnifeHit => self.knife_hit.clone(),
            Sfx::KnifeSwish => self.knife_swish.clone(),
            Sfx::Sniper => self.sniper.clone(),
            Sfx::Explosion => self.explosion.clone(),
            Sfx::Reload => self.reload.clone(),
            Sfx::Plip => self.plip.clone(),
            Sfx::Hit => self.hit.clone(),
        }
    }
}

/// Per-sound mix: (gain, how hard it ducks the music). Gains leave headroom: Bevy sums
/// overlapping sounds, and anything over full scale hard-clips.
fn mix(s: Sfx) -> (f32, f32) {
    match s {
        Sfx::Ak => (0.48, 0.30),
        Sfx::Pistol => (0.48, 0.25),
        Sfx::M50 => (0.52, 0.30),
        Sfx::KnifeHit => (0.70, 0.05),
        Sfx::KnifeSwish => (0.45, 0.0),
        Sfx::Sniper => (0.72, 0.70),
        Sfx::Explosion => (0.78, 1.00),
        Sfx::Reload => (0.50, 0.0),
        Sfx::Plip => (0.55, 0.0),
        Sfx::Hit => (0.70, 0.40),
    }
}

fn load_f32(a: &std::sync::atomic::AtomicU32) -> f32 {
    f32::from_bits(a.load(std::sync::atomic::Ordering::Relaxed))
}

fn store_f32(a: &std::sync::atomic::AtomicU32, v: f32) {
    a.store(v.to_bits(), std::sync::atomic::Ordering::Relaxed);
}

impl Fx {
    /// Raise the music-ducking level (it decays in `music`).
    fn duck_to(&self, v: f32) {
        store_f32(&self.duck, load_f32(&self.duck).max(v.min(1.0)));
    }

    /// Effects volume (keys , and .).
    pub fn sfx_gain(&self) -> f32 {
        load_f32(&self.sfx_gain)
    }

    /// Play a one-shot effect. `r` (0..1) picks a variation; `speed` varies the pitch a little.
    pub fn play(&self, commands: &mut Commands, s: Sfx, volume: f32, speed: f32, r: f32) {
        if self.muted || volume <= 0.01 {
            return;
        }
        let (gain, duck) = mix(s);
        self.duck_to(duck * volume.min(1.0));
        commands.spawn((
            AudioPlayer::new(self.audio.pick(s, r)),
            PlaybackSettings {
                mode: PlaybackMode::Despawn,
                volume: Volume::Linear((gain * volume.min(1.2) * self.sfx_gain()).clamp(0.0, 1.5)),
                speed,
                ..PlaybackSettings::ONCE
            },
        ));
    }

    /// A looping bed that lasts as long as the level.
    pub fn bed(&self, commands: &mut Commands, handle: Handle<AudioSource>, volume: f32) {
        if self.muted {
            return;
        }
        commands.spawn((
            AudioPlayer::new(handle),
            PlaybackSettings {
                volume: Volume::Linear(volume),
                ..PlaybackSettings::LOOP
            },
            LevelEntity,
        ));
    }

    pub fn ambience(&self, commands: &mut Commands, volume: f32) {
        self.bed(commands, self.audio.ambience.clone(), volume);
    }

    pub fn heli_loop(&self, commands: &mut Commands, volume: f32) {
        self.bed(commands, self.audio.heli.clone(), volume);
    }
}

// ----------------------------------------------------------------- music

#[derive(Component)]
pub struct MusicLayer {
    pub tense: bool,
}

#[derive(Resource)]
pub struct Intensity {
    /// 0 calm .. 1 hunted (smoothed).
    pub v: f32,
    pub music_on: bool,
    /// Music volume, 0..1 (keys [ and ]).
    pub level: f32,
}

impl Default for Intensity {
    fn default() -> Self {
        Self { v: 0.0, music_on: true, level: 1.0 }
    }
}

const MUSIC_VOLUME: f32 = 0.78;
/// The tense loop is about 3.4 dB louder to the ear than the calm one (measured); trim it.
const TENSE_TRIM: f32 = 0.7;

/// Keep both music loops running and crossfade by how hunted Ro is.
#[allow(clippy::too_many_arguments)]
pub fn music(
    time: Res<Time>,
    keys: Res<ButtonInput<KeyCode>>,
    fx: Res<Fx>,
    mut commands: Commands,
    mut intensity: ResMut<Intensity>,
    mut layers: Query<(&MusicLayer, Option<&mut AudioSink>)>,
    guards: Query<&Guard>,
    grab: Res<crate::level3::Grab>,
    health: Res<Health>,
    mut msg: ResMut<Message>,
) {
    if fx.muted {
        return;
    }
    let dt = time.delta_secs().min(0.1);
    if keys.just_pressed(KeyCode::KeyM) {
        intensity.music_on = !intensity.music_on;
    }
    if keys.just_pressed(KeyCode::BracketLeft) {
        intensity.level = (intensity.level - 0.1).max(0.0);
        msg.0 = format!("Music {:.0}%", intensity.level * 100.0);
    }
    if keys.just_pressed(KeyCode::BracketRight) {
        intensity.level = (intensity.level + 0.1).min(1.0);
        msg.0 = format!("Music {:.0}%", intensity.level * 100.0);
    }
    if keys.just_pressed(KeyCode::Comma) || keys.just_pressed(KeyCode::Period) {
        let step = if keys.just_pressed(KeyCode::Comma) { -0.1 } else { 0.1 };
        let g = (load_f32(&fx.sfx_gain) + step).clamp(0.0, 1.5);
        store_f32(&fx.sfx_gain, g);
        msg.0 = format!("Effects {:.0}%", g * 100.0);
    }
    if layers.is_empty() {
        for tense in [false, true] {
            commands.spawn((
                MusicLayer { tense },
                AudioPlayer::new(if tense { fx.audio.tense.clone() } else { fx.audio.calm.clone() }),
                PlaybackSettings {
                    volume: Volume::Linear(0.0),
                    ..PlaybackSettings::LOOP
                },
            ));
        }
        return;
    }

    // How dangerous is it right now?
    let mut target = 0.0_f32;
    for g in &guards {
        if g.status != LostStatus::Standing {
            continue;
        }
        let v = match g.state {
            AiState::Chase => 1.0,
            AiState::Investigate => 0.55,
            AiState::Suspicious => 0.4,
            AiState::Search => 0.3,
            AiState::Patrol => 0.0,
        };
        target = target.max(v);
    }
    if grab.0 > 0 {
        target = target.max(0.6);
    }
    if health.hurt > 0.3 {
        target = target.max(0.8);
    }
    if health.hp < 35.0 {
        target = target.max(0.7);
    }
    // Rise quickly, fall slowly.
    let rate = if target > intensity.v { 1.2 } else { 0.25 };
    intensity.v += (target - intensity.v).clamp(-rate * dt, rate * dt);

    // Loud sounds push the music down for a moment, then it comes back.
    let duck = load_f32(&fx.duck);
    store_f32(&fx.duck, (duck - 2.4 * dt).max(0.0));
    let master = if intensity.music_on { MUSIC_VOLUME * intensity.level } else { 0.0 } * (1.0 - 0.5 * duck);
    // Equal-power crossfade; the calm bed never fully leaves, so the level stays even.
    let a = intensity.v * std::f32::consts::FRAC_PI_2;
    for (layer, sink) in &mut layers {
        if let Some(mut sink) = sink {
            let v = if layer.tense {
                a.sin() * 0.9 * TENSE_TRIM
            } else {
                0.4 + 0.6 * a.cos()
            };
            sink.set_volume(Volume::Linear(v * master));
        }
    }
}

pub fn stop_music(mut commands: Commands, layers: Query<Entity, With<MusicLayer>>) {
    for e in &layers {
        commands.entity(e).despawn();
    }
}

/// A dull thud whenever Ro is hurt.
pub fn hurt_sfx(
    fx: Res<Fx>,
    health: Res<Health>,
    mut commands: Commands,
    mut last: Local<f32>,
    mut rng: ResMut<crate::weapons::Rng>,
) {
    if health.hp < *last - 4.0 {
        fx.play(&mut commands, Sfx::Hit, 1.0, 0.95 + 0.1 * rng.next(), 0.0);
    }
    *last = health.hp;
}

/// `WSR_AUDIOTEST=1`: play every sound once and report what loaded.
pub fn audio_test(
    time: Res<Time>,
    server: Res<AssetServer>,
    fx: Res<Fx>,
    mut commands: Commands,
    mut step: Local<u32>,
    sinks: Query<&AudioSink>,
) {
    let t = time.elapsed_secs();
    let all: [(&str, Handle<AudioSource>); 14] = [
        ("ak_1", fx.audio.ak[0].clone()),
        ("pistol_1", fx.audio.pistol[0].clone()),
        ("m50_1", fx.audio.m50[0].clone()),
        ("knife_hit", fx.audio.knife_hit.clone()),
        ("knife_swish", fx.audio.knife_swish.clone()),
        ("sniper", fx.audio.sniper.clone()),
        ("explosion", fx.audio.explosion.clone()),
        ("reload", fx.audio.reload.clone()),
        ("plip", fx.audio.plip.clone()),
        ("hit", fx.audio.hit.clone()),
        ("heli", fx.audio.heli.clone()),
        ("ambience", fx.audio.ambience.clone()),
        ("calm", fx.audio.calm.clone()),
        ("tense", fx.audio.tense.clone()),
    ];
    if *step == 0 && t > 3.0 {
        *step = 1;
        for (name, h) in &all {
            eprintln!("[audiotest] {name}: {:?}", server.load_state(h));
        }
        for (i, s) in [Sfx::Ak, Sfx::Pistol, Sfx::M50, Sfx::KnifeHit, Sfx::Sniper, Sfx::Explosion, Sfx::Plip].into_iter().enumerate() {
            let _ = i;
            fx.play(&mut commands, s, 0.7, 1.0, 0.3);
        }
    }
    if *step == 1 && t > 5.0 {
        *step = 2;
        eprintln!("[audiotest] live audio sinks (music layers + one-shots still playing): {}", sinks.iter().count());
    }
}

// ----------------------------------------------------------- introduction music

#[derive(Component)]
pub struct IntroMusic;

/// The file is mastered at about -26 LUFS, about 9 dB under the music of the game; played at 0.7 (about 3 dB lower still): a bed to read by.
const INTRO_VOLUME: f32 = 0.7;

/// The mystery loop (tools/intro_music.py) plays under the disclaimer and the story cards, over and over until
/// ENTER starts the game; it rises slowly when the game opens and fades away when play begins.
pub fn intro_music(
    time: Res<Time>,
    keys: Res<ButtonInput<KeyCode>>,
    fx: Res<Fx>,
    state: Res<State<AppState>>,
    mut intensity: ResMut<Intensity>,
    mut commands: Commands,
    mut tracks: Query<(Entity, Option<&mut AudioSink>), With<IntroMusic>>,
    mut vol: Local<f32>,
) {
    if keys.just_pressed(KeyCode::KeyM) && matches!(state.get(), AppState::Disclaimer | AppState::Pitch) {
        intensity.music_on = !intensity.music_on;
    }
    if fx.muted {
        return;
    }
    let want = matches!(state.get(), AppState::Disclaimer | AppState::Pitch);
    let target = if want && intensity.music_on { INTRO_VOLUME * intensity.level } else { 0.0 };
    let dt = time.delta_secs().min(0.1);
    // slow in (about 4 s), quicker out (about 1.5 s)
    let rate = if target > *vol { 0.25 } else { 0.7 };
    *vol += (target - *vol).clamp(-rate * dt, rate * dt);
    if tracks.is_empty() {
        if want {
            commands.spawn((
                IntroMusic,
                AudioPlayer::new(fx.audio.intro.clone()),
                PlaybackSettings {
                    volume: Volume::Linear(0.0),
                    ..PlaybackSettings::LOOP
                },
            ));
        }
        return;
    }
    for (e, sink) in &mut tracks {
        if !want && *vol < 0.005 {
            commands.entity(e).despawn();
        } else if let Some(mut sink) = sink {
            sink.set_volume(Volume::Linear(*vol));
        }
    }
}
